--
-- Vaultora: Push Local Database to Remote Supabase Instance
--
SET statement_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;

-- Temporarily disable triggers and foreign-key checks for bulk insertion
SET session_replication_role = 'replica';

-- Clean existing tables to avoid duplicate key conflicts
TRUNCATE TABLE
    email_verification_tokens,
    password_reset_tokens,
    maker_checker_requests,
    account_requests,
    audit_logs,
    transaction_limits,
    ledger_entries,
    ledger_transactions,
    accounts,
    users
CASCADE;

-- Table: users (30 records)

-- Table: accounts (40 records)

-- Table: ledger_transactions (23 records)

-- Table: ledger_entries (46 records)

-- Table: transaction_limits (1 records)

-- Table: account_requests (5 records)

-- Table: audit_logs (345 records)

-- Table: email_verification_tokens (1 records)

-- Restore triggers and foreign-key enforcement
SET session_replication_role = 'origin';
